using System.IO;
namespace Hisab;
public static class ItemHistoryTests
{
    public static void Run(string directory,List<string> results)
    {
        using var s=new Store(Path.Combine(directory,"history-"+Guid.NewGuid()+".db"));var a=new AccountingService(s);var today=DateTime.Today;
        void Check(bool ok,string message){if(!ok)throw new Exception(message);results.Add("PASS "+message);}
        var customer=s.Accounts().First(x=>x.Kind=="Unclassified");s.SaveAccount(customer.Id,customer.Code,customer.Name,"Customer");var supplier=s.Accounts().First(x=>x.Kind=="Unclassified");s.SaveAccount(supplier.Id,supplier.Code,supplier.Name,"Supplier");
        long item=s.Items()[0].Id,other=s.SaveLocation(null,"History warehouse");a.ConfigureInventoryItem(item,"HISTORY",true,[]);
        long purchase=a.Invoice(false,today.AddDays(-1),supplier.Id,null,0,0,false,"Purchase history",[new(item,"Device",1,100,0,1,"H1"),new(item,"Device",1,100,0,1,"H2")]);
        var rows=s.ItemHistory(item);var buy=rows.Single(r=>r.Id==purchase&&r.Source=="document");Check(buy.Incoming==2000&&buy.DocumentQuantity==2000&&buy.Serials.Split('\n').Length==2,"Item history groups duplicate lines without duplicating serial quantities");
        long transfer=a.TransferInventory(today,1,other,item,1,"H1","Moved");rows=s.ItemHistory(item);Check(rows.Count(r=>r.Id==transfer&&r.Source=="document")==2&&rows.Where(r=>r.Id==transfer&&r.Source=="document").Sum(r=>r.EffectiveChange)==0,"Item history shows both transfer locations without changing company stock");
        long sale=a.Invoice(true,today,customer.Id,null,0,0,false,"Customer sale",[new(item,"Device",1,150,0,other,"H1")]);long line=Convert.ToInt64(s.Scalar("SELECT id FROM invoice_lines WHERE doc=@p0",sale));long ret=a.ReturnInvoice(sale,today,[new(line,1,"H1")],"Customer return");
        Check(s.ItemHistory(item).Single(r=>r.Id==ret&&r.Source=="document").Incoming==1000,"Item history includes customer returns");
        a.Reverse(ret,"Undo return");long reversal=a.Reverse(sale,"Undo sale");rows=s.ItemHistory(item);var rv=rows.Single(r=>r.Id==reversal&&r.Source=="document");Check(rv.Location==other&&rv.Incoming==1000&&rv.Serials=="H1","Item history reversal inherits original location and serials");
        Check(rows.Single(r=>r.Id==sale&&r.Source=="document").State=="Cancelled"&&rows.Where(r=>r.State is "Cancelled" or "Reversal").All(r=>r.EffectiveChange==0),"Cancelled activity and reversals cannot inflate current stock");
        Check(s.Locations(false).All(l=>rows.Where(r=>r.Location==l.Id).Sum(r=>r.EffectiveChange)==s.LocationQuantity(item,l.Id)),"History effective quantities reconcile with each stock location");
        long hold=a.CreateReservation(customer.Id,today.AddDays(2),[new(item,other,1,"H1")],"Collection");var reserved=s.ItemHistory(item).Single(r=>r.Source=="reservation"&&r.Id==hold);Check(reserved.DocumentQuantity==1000&&reserved.EffectiveChange==0&&reserved.State=="Active","Reservations appear without physical stock movement");a.ReleaseReservation(hold,"Cancelled collection");Check(s.ItemHistory(item).Single(r=>r.Source=="reservation"&&r.Id==hold).State=="Released","History uses current reservation status after release");
        rows=s.ItemHistory(item);Check(Store.FilterItemHistory(rows,today,today,other,"IT").Count==1,"Item history combines inclusive date location and activity filters");Check(Store.FilterItemHistory(rows,search:"h2").Single().Id==purchase,"Item history serial search is case insensitive");Check(Store.FilterItemHistory(rows,search:"no-such-record").Count==0&&Store.FilterItemHistory(rows,to:today.AddDays(-2)).Count==0,"Unmatched history filters produce an empty result");
        bool rejected=false;try{Store.FilterItemHistory(rows,today,today.AddDays(-1));}catch(InvalidOperationException){rejected=true;}Check(rejected,"Invalid item history date range is rejected");
        long receiptItem=s.Items()[1].Id;long order=a.CreatePurchaseOrder(supplier.Id,1,today,[new(receiptItem,3,50)]);a.IssuePurchaseOrder(order);long orderLine=Convert.ToInt64(s.Scalar("SELECT id FROM purchase_order_lines WHERE order_id=@p0",order));long receipt=a.ReceivePurchaseOrder(order,today,[new(orderLine,3,"")]);long receiptLine=Convert.ToInt64(s.Scalar("SELECT id FROM invoice_lines WHERE doc=@p0",receipt));long bill=a.BillReceipts(supplier.Id,today,[new(receiptLine,2,50)],0);long freight=a.AddLandedCost(today,supplier.Id,null,30,[new(receiptLine,30)],"Freight");
        var procurement=s.ItemHistory(receiptItem);Check(procurement.Single(r=>r.Id==receipt).Incoming==3000&&procurement.Single(r=>r.Id==bill).Incoming==0&&procurement.Single(r=>r.Id==bill).DocumentQuantity==2000,"Receipt billing appears without counting stock twice");Check(procurement.Single(r=>r.Id==freight).Kind=="LC"&&procurement.Single(r=>r.Id==freight).EffectiveChange==0,"Item history links landed costs without inventing quantities");
        long count=a.StartStockCount(1,[receiptItem]);a.RecordStockCount(count,receiptItem,2,"",50);long adjustment=a.CompleteStockCount(count,"Missing unit");Check(s.ItemHistory(receiptItem).Single(r=>r.Id==adjustment).Outgoing==1000,"Item history includes stock count losses");
        long audits=Convert.ToInt64(s.Scalar("SELECT count(*) FROM audit"));var quantities=s.Items().Select(i=>i.Qty).ToList();s.ItemHistory(item);s.ItemHistory(receiptItem);Check(audits==Convert.ToInt64(s.Scalar("SELECT count(*) FROM audit"))&&quantities.SequenceEqual(s.Items().Select(i=>i.Qty)),"Reading item history does not mutate stock or audit data");
        Check(s.ItemHistory(s.Items()[2].Id).Count==0,"Unused items have empty history");
        long transferReversal=a.Reverse(transfer,"Undo transfer");var transferRows=s.ItemHistory(item).Where(r=>r.Source=="document"&&r.Id==transferReversal).ToList();Check(transferRows.Count==2&&transferRows.Single(r=>r.Location==1).Incoming==1000&&transferRows.Single(r=>r.Location==other).Outgoing==1000,"Reversed transfers retain both original locations and directions");
        s.SaveLocation(other,"History warehouse",false);Check(s.ItemHistory(item).Any(r=>r.Location==other),"History retains inactive stock locations");
        var service=s.Items()[2];s.SaveItem(service.Id,service.Code,service.Name,false,0);long serviceSale=a.Invoice(true,today,customer.Id,null,0,0,false,"Service",[new(service.Id,"Installation",2,20,0)]);var serviceEntry=s.ItemHistory(service.Id).Single();Check(serviceEntry.Id==serviceSale&&serviceEntry.DocumentQuantity==2000&&serviceEntry.Incoming==0&&serviceEntry.Outgoing==0,"Service invoice history carries document quantity without stock movement");
        long returnItem=s.Items()[3].Id;long directPurchase=a.Invoice(false,today,supplier.Id,null,0,0,false,"Returnable",[new(returnItem,"Part",2,50,0)]);long returnLine=Convert.ToInt64(s.Scalar("SELECT id FROM invoice_lines WHERE doc=@p0",directPurchase));long supplierReturn=a.ReturnInvoice(directPurchase,today,[new(returnLine,1)],"Faulty part");Check(s.ItemHistory(returnItem).Single(r=>r.Id==supplierReturn).Outgoing==1000,"Item history includes supplier returns");

    }
}
